  function q(o) {
    const correct = o.ans.map(i => `${letters(i)}. ${o.opts[i]}`).join(" / ");
    const incorrectReasons = {};
    o.opts.forEach((opt,i)=>{ if(!o.ans.includes(i)) incorrectReasons[i]=conceptReason(opt,o.clue); });
    return {
      q:o.q, opts:o.opts, ans:o.ans, selectCount:o.ans.length>1?o.ans.length:1,
      why:o.why,
      explanation:{
        correctAnswer:correct,
        correctReason:o.why + ` The decisive clue is **${o.clue}**.`,
        incorrectReasons,
        examClue:o.clue,
        examTip:o.tip,
        transferCheck:o.transferCheck||"",
        rememberThis:o.tip,
        takeaway:{signal:o.clue,think:o.tip,contrast:o.contrast||""}
      },
      status:"imported mock question",
      task:"Mock Exam",
      taskName:"AIF-C01 mixed-domain practice",
      difficulty:"exam-style",
      source:"ExamPrepper",
      sourceQuestion:o.sourceNumber
    };
  }

  function match(o) {
    return {
      type:"matching", q:o.q, rows:o.rows, choices:o.choices, ans:o.ans, why:o.why,
      explanation:{
        correctAnswer:o.rows.map((r,i)=>`${r} → ${o.choices[o.ans[i]]}`).join(" | "),
        correctReason:o.why + ` The decisive clue is **${o.clue}**.`,
        incorrectReasons:{},
        examClue:o.clue,
        examTip:o.tip,
        transferCheck:o.transferCheck||"",
        rememberThis:o.tip,
        takeaway:{signal:o.clue,think:o.tip,contrast:o.contrast||""}
      },
      status:"imported hotspot/matching question",
      task:"Mock Exam",
      taskName:"AIF-C01 mixed-domain practice",
      difficulty:"exam-style",
      source:"ExamPrepper",
      sourceQuestion:o.sourceNumber
    };
  }

  const raw = [{"q":"A medical company wants to process patient records that contain clinical text, extract relevant medical information, and generate concise structured summaries. Which solution BEST meets these requirements?","opts":["Use Amazon Comprehend Medical to extract relevant medical entities and relationships. Apply rule-based logic to structure and format summaries.","Use Amazon Personalize to analyze patient engagement patterns. Integrate the output with a general purpose text summarization tool.","Use Amazon Textract to convert scanned documents into digital text. Design a keyword extraction system to generate summaries.","Implement Amazon Kendra to provide a searchable index for medical records. Use a template-based system to format summaries."],"ans":[0],"why":"Amazon Comprehend Medical is the healthcare-specific NLP service among these choices. It can identify medical entities and relationships from clinical text, after which application logic can organize the extracted information into concise summaries.","clue":"medical records + extract medical entities and relationships","tip":"Medical text understanding → Comprehend Medical. Scanned document OCR → Textract; enterprise search → Kendra.","sourceNumber":66},{"q":"Which option describes embeddings in the context of AI?","opts":["A method for compressing large datasets","An encryption method for securing sensitive data","A method for visualizing high-dimensional data","A numerical vector representation that captures semantic relationships among data"],"ans":[3],"why":"Embeddings encode items such as text or images as numerical vectors that capture semantic relationships. Similar items are represented by vectors that are close to one another according to a similarity measure.","clue":"numerical vectors that preserve semantic relationships","tip":"Embeddings = semantic vectors; similar meaning → nearby vectors.","sourceNumber":67,"contrast":"Embeddings are often high-dimensional. Do not confuse them with dimensionality-reduction visualizations such as PCA or t-SNE."},{"q":"A company is building a contact center application and wants to gain insights from customer conversations. The company wants to analyze and extract key information from the audio of the customer calls. Which solution meets these requirements?","opts":["Build a conversational chatbot by using Amazon Lex.","Transcribe call recordings by using Amazon Transcribe.","Extract information from call recordings by using Amazon SageMaker Model Monitor.","Create classification labels by using Amazon Comprehend."],"ans":[1],"why":"Amazon Transcribe is the AWS speech-to-text service and includes contact-center-oriented capabilities for turning call audio into text that can then be analyzed. The other options do not directly process call audio for transcription.","clue":"customer call audio","tip":"Speech/audio → text = Amazon Transcribe. Text analysis afterward can use Comprehend.","sourceNumber":68},{"q":"A company is building an AI application to summarize books of varying lengths. During testing, the application fails to summarize some books. Why does the application fail to summarize some books?","opts":["The temperature is set too high.","The selected model does not support fine-tuning.","The Top P value is too high.","The input tokens exceed the model’s context size."],"ans":[3],"why":"Every foundation model has a maximum context window. If a book plus the requested output exceeds that token limit, the model cannot accept the entire input as one request.","clue":"books of varying lengths + only some long books fail","tip":"Too much input text → think tokens/context window, not temperature or Top P.","sourceNumber":69},{"q":"An airline company wants to build a conversational AI assistant to answer customer questions about flight schedules, booking, and payments. The company wants to use large language models (LLMs) and a knowledge base to create a text-based chatbot interface. Which solution will meet these requirements with the LEAST development effort?","opts":["Train models on Amazon SageMaker Autopilot.","Develop a Retrieval Augmented Generation (RAG) agent by using Amazon Bedrock.","Create a Python application by using Amazon Q Developer.","Fine-tune models on Amazon SageMaker JumpStart."],"ans":[1],"why":"Amazon Bedrock provides managed foundation models, Knowledge Bases for RAG, and Agents for orchestration, which directly match a chatbot that must use enterprise knowledge and take actions with minimal custom ML infrastructure.","clue":"LLM + knowledge base + conversational assistant + LEAST development effort","tip":"Managed GenAI + RAG/agents → Amazon Bedrock.","sourceNumber":70},{"q":"What is tokenization used for in natural language processing (NLP)?","opts":["To encrypt text data","To compress text files","To break text into smaller units for processing","To translate text between languages"],"ans":[2],"why":"Tokenization breaks text into tokens—such as words, subwords, or pieces—that a language model can process.","clue":"tokenization","tip":"Tokenization = text → smaller model-processing units.","sourceNumber":71},{"q":"Which option is a characteristic of transformer-based language models?","opts":["Transformer-based language models use convolutional layers to apply filters across an input to capture local patterns through filtered views.","Transformer-based language models can process only text data.","Transformer-based language models use self-attention mechanisms to capture contextual relationships.","Transformer-based language models process data sequences one element at a time in cyclic iterations."],"ans":[2],"why":"The defining transformer mechanism tested at AIF-C01 level is self-attention, which lets the model weigh relationships among tokens across a sequence and capture context.","clue":"transformer architecture","tip":"Transformer → self-attention. RNNs are the sequence-one-step-at-a-time trap.","sourceNumber":72},{"q":"A financial company is using AI systems to obtain customer credit scores as part of the loan application process. The company wants to expand to a new market in a different geographic area. The company must ensure that it can operate in that geographic area. Which compliance laws should the company review?","opts":["Local health data protection laws","Local payment card data protection laws","Local education privacy laws","Local algorithm accountability laws"],"ans":[3],"why":"The system is making or supporting consequential automated credit decisions. When entering a new jurisdiction, the company should review local laws governing automated decision-making and algorithmic accountability.","clue":"AI credit scoring + new geographic market","tip":"Match the law to the data/use case: automated decisions → algorithm accountability.","sourceNumber":73},{"q":"A company uses Amazon Bedrock for its generative AI application. The company wants to use Amazon Bedrock Guardrails to detect and filter harmful user inputs and model-generated outputs. Which content categories can the guardrails filter? (Choose two.)","opts":["Hate","Politics","Violence","Gambling","Religion"],"ans":[0,2],"why":"Amazon Bedrock Guardrails content filters include predefined harmful-content categories such as Hate and Violence. Politics, gambling, and religion are not predefined content-filter categories, though a company could define application-specific denied topics.","clue":"Bedrock Guardrails predefined content categories","tip":"Memorize Guardrails content filters: Hate, Insults, Sexual, Violence, Misconduct, Prompt Attack.","sourceNumber":74},{"q":"Which option describes a security risk that can be introduced through prompts in a generative AI application?","opts":["Prompt engineering does not ensure that the model always produces consistent and deterministic outputs, eliminating the need for validation.","Prompt engineering could expose the model to vulnerabilities such as prompt injection attacks.","Properly designed prompts reduce but do not eliminate the risk of data poisoning or model hijacking.","Prompt engineering does not ensure that the model will consistently generate highly reliable outputs when working with real-world data."],"ans":[1],"why":"Prompt injection is a prompt-interface attack in which malicious input attempts to override, manipulate, or bypass the application’s intended instructions.","clue":"malicious input through the prompt interface","tip":"User input tries to override developer/system instructions → prompt injection.","sourceNumber":75,"contrast":"Data poisoning is primarily a training-data threat; general output unreliability is a model limitation rather than the prompt-specific security attack asked here."},{"q":"A publishing company built a Retrieval Augmented Generation (RAG) based solution to give its users the ability to interact with published content. New content is published daily. The company wants to provide a near real-time experience to users. Which steps in the RAG pipeline should the company implement by using offline batch processing to meet these requirements? (Choose two.)","opts":["Generation of content embeddings","Generation of embeddings for user queries","Creation of the search index","Retrieval of relevant content","Response generation for the user"],"ans":[0,2],"why":"The document-side work can be prepared offline: generate embeddings for newly published content and update/build the searchable index. Query embedding, retrieval, and response generation must happen online for the user's near-real-time interaction.","clue":"offline batch processing in a near-real-time RAG system","tip":"RAG offline = ingest/chunk/embed/index documents. RAG online = embed query/retrieve/generate.","sourceNumber":76},{"q":"Which technique breaks a complex task into smaller subtasks that are sent sequentially to a large language model (LLM)?","opts":["One-shot prompting","Prompt chaining","Tree of thoughts","Retrieval Augmented Generation (RAG)"],"ans":[1],"why":"Prompt chaining decomposes a larger task into a sequence of prompts where the output of one step can feed the next step.","clue":"smaller subtasks sent sequentially","tip":"Sequential prompts → prompt chaining.","sourceNumber":77},{"q":"An AI practitioner needs to improve the accuracy of a natural language generation model. The model uses rapidly changing inventory data. Which technique will improve the model's accuracy?","opts":["Transfer learning","Federated learning","Retrieval Augmented Generation (RAG)","One-shot prompting"],"ans":[2],"why":"RAG retrieves current external information at inference time, so rapidly changing inventory can be incorporated without repeatedly retraining the model.","clue":"rapidly changing data","tip":"Current/private facts that change often → RAG, not fine-tuning.","sourceNumber":78},{"q":"A company has petabytes of unlabeled customer data to use for an advertisement campaign. The company wants to classify its customers into tiers to advertise and promote the company's products. Which methodology should the company use to meet these requirements?","opts":["Supervised learning","Unsupervised learning","Reinforcement learning","Reinforcement learning from human feedback (RLHF)"],"ans":[1],"why":"Because the data is unlabeled, the company should use unsupervised methods such as clustering to discover natural customer groups or tiers.","clue":"petabytes of unlabeled customer data + group into tiers","tip":"Unlabeled + group similar customers → unsupervised learning/clustering.","sourceNumber":79},{"q":"A company wants to collaborate with several research institutes to develop an AI model. The company needs standardized documentation of model version tracking and a record of model development. Which solution meets these requirements?","opts":["Track the model changes by using Git.","Track the model changes by using Amazon Fraud Detector.","Track the model changes by using Amazon SageMaker Model Cards.","Track the model changes by using Amazon Comprehend."],"ans":[2],"why":"SageMaker Model Cards provide standardized model documentation, including intended use, risk, training/evaluation details, and model-development information that supports governance across collaborating teams.","clue":"standardized documentation + model development record","tip":"Model documentation/governance artifact → SageMaker Model Cards.","sourceNumber":80},{"q":"A company that uses multiple ML models wants to identify changes in original model quality so that the company can resolve any issues. Which AWS service or feature meets these requirements?","opts":["Amazon SageMaker JumpStart","Amazon SageMaker HyperPod","Amazon SageMaker Data Wrangler","Amazon SageMaker Model Monitor"],"ans":[3],"why":"SageMaker Model Monitor continuously monitors deployed models for changes in data quality and model quality so teams can detect degradation and drift.","clue":"changes in model quality after deployment","tip":"Production drift/degradation → SageMaker Model Monitor.","sourceNumber":81},{"q":"What is the purpose of chunking in Retrieval Augmented Generation (RAG)?","opts":["To avoid database storage limitations for large text documents by storing parts or chunks of the text","To improve efficiency by avoiding the need to convert large text into vector embeddings","To improve the contextual relevancy of results retrieved from the vector index","To decrease the cost of storage by storing parts or chunks of the text"],"ans":[2],"why":"Chunking splits documents into retrieval-sized passages so vector search can return the most relevant context instead of an entire large document. This improves retrieval precision and the usefulness of context given to the model.","clue":"RAG chunking","tip":"Chunking is about retrieval relevance/context quality—not avoiding embeddings or saving storage.","sourceNumber":82},{"q":"A company is developing an editorial assistant application that uses generative AI. During the pilot phase, usage is low and application performance is not a concern. The company cannot predict application usage after the application is fully deployed and wants to minimize application costs. Which solution will meet these requirements?","opts":["Use GPU-powered Amazon EC2 instances.","Use Amazon Bedrock with Provisioned Throughput.","Use Amazon Bedrock with On-Demand Throughput.","Use Amazon SageMaker JumpStart."],"ans":[2],"why":"Bedrock On-Demand Throughput is pay-per-use and avoids reserving capacity. It is a strong fit for low or uncertain request volume when the company wants to avoid paying for idle capacity.","clue":"low usage + unpredictable future usage + minimize cost","tip":"Uncertain/spiky Bedrock usage → On-Demand. Steady guaranteed capacity → Provisioned Throughput.","sourceNumber":83},{"q":"A company deployed a Retrieval Augmented Generation (RAG) application on Amazon Bedrock that gathers financial news to distribute in daily newsletters. Users have recently reported politically influenced ideas in the newsletters. Which Amazon Bedrock guardrail can identify and filter this content?","opts":["Word filters","Denied topics","Sensitive information filters","Content filters"],"ans":[1],"why":"Politics is not one of Bedrock Guardrails' predefined harmful-content categories. A company can define politics or political advocacy as a denied topic and block matching prompts or responses contextually.","clue":"block an application-specific topic such as politics","tip":"Custom subject/theme to block → Denied topics. Exact terms → Word filters.","sourceNumber":84},{"q":"A financial company is developing a fraud detection system that flags potential fraud cases in credit card transactions. Employees will evaluate the flagged fraud cases. The company wants to minimize the amount of time the employees spend reviewing flagged fraud cases that are not actually fraudulent. Which evaluation metric meets these requirements?","opts":["Recall","Accuracy","Precision","Lift chart"],"ans":[2],"why":"The company wants the positive predictions (flagged transactions) to be trustworthy. Precision measures how many predicted positives are truly positive, so higher precision means fewer false-positive fraud alerts for employees to review.","clue":"minimize false alarms / false positives","tip":"False positives are expensive → precision. Missing positives is expensive → recall.","sourceNumber":85},{"q":"A company designed an AI-powered agent to answer customer inquiries based on product manuals. Which strategy can improve customer confidence levels in the AI-powered agent's responses?","opts":["Writing the confidence level in the response","Including referenced product manual links in the response","Designing an agent avatar that looks like a computer","Training the agent to respond in the company's language style"],"ans":[1],"why":"Providing citations or links to the product manuals lets customers verify the source behind an answer. Source attribution improves transparency and trust more than cosmetic presentation or an uncalibrated confidence number.","clue":"increase confidence in answers grounded in product manuals","tip":"Trust in grounded responses → provide citations/source references.","sourceNumber":86},{"q":"A hospital developed an AI system to provide personalized treatment recommendations for patients. The AI system must provide the rationale behind the recommendations and make the insights accessible to doctors and patients. Which human-centered design principle does this scenario present?","opts":["Explainability","Privacy and security","Fairness","Data governance"],"ans":[0],"why":"Explainability means users can understand the rationale or factors behind an AI system's output. The scenario explicitly requires reasons behind treatment recommendations.","clue":"provide the rationale behind recommendations","tip":"'Why did the model decide this?' → explainability.","sourceNumber":87},{"q":"Which statement presents an advantage of using Retrieval Augmented Generation (RAG) for natural language processing (NLP) tasks?","opts":["RAG can use external knowledge sources to generate more accurate and informative responses.","RAG is designed to improve the speed of language model training.","RAG is primarily used for speech recognition tasks.","RAG is a technique for data augmentation in computer vision tasks."],"ans":[0],"why":"RAG retrieves relevant information from external knowledge sources at inference time and supplies it as context, improving factual grounding without retraining the foundation model.","clue":"RAG advantage","tip":"RAG = retrieve external knowledge → ground generation.","sourceNumber":88},{"q":"A company has created a custom model by fine-tuning an existing large language model (LLM) from Amazon Bedrock. The company wants to deploy the model to production and use the model to handle a steady rate of requests each minute. Which solution meets these requirements MOST cost-effectively?","opts":["Deploy the model by using an Amazon EC2 compute optimized instance.","Use the model with on-demand throughput on Amazon Bedrock.","Store the model in Amazon S3 and host the model by using AWS Lambda.","Purchase Provisioned Throughput for the model on Amazon Bedrock."],"ans":[3],"why":"For the source scenario, a fine-tuned Bedrock custom model with steady, predictable request volume maps to Provisioned Throughput, which reserves model capacity for consistent production use.","clue":"fine-tuned Bedrock model + steady request rate","tip":"Steady predictable Bedrock capacity, especially for custom models in exam scenarios → Provisioned Throughput.","sourceNumber":89,"contrast":"Bedrock capabilities evolve, so read the exam scenario's custom-model and steady-throughput clues rather than assuming every base-model pricing option applies identically."},{"q":"An AI practitioner wants to use a foundation model (FM) to design a search application. The search application must handle queries that have text and images. Which type of FM should the AI practitioner use to power the search application?","opts":["Multi-modal embedding model","Text embedding model","Multi-modal generation model","Image generation model"],"ans":[0],"why":"A multimodal embedding model can represent both text and image content in vector space so semantically related text and images can be compared for search and retrieval.","clue":"search across text and images","tip":"Search/similarity → embeddings. Multiple input types → multimodal embeddings.","sourceNumber":90},{"q":"Which technique involves training AI models on labeled datasets to adapt the models to specific industry terminology and requirements?","opts":["Data augmentation","Fine-tuning","Model quantization","Continuous pre-training"],"ans":[1],"why":"Fine-tuning continues training a pre-trained model on labeled, task-specific examples so the model adapts its behavior to a specialized use case or domain.","clue":"labeled dataset + adapt to a specific task/domain","tip":"Labeled task examples → fine-tuning. Unlabeled domain corpus → continued pre-training.","sourceNumber":91},{"q":"A company is creating an agent for its application by using Amazon Bedrock Agents. The agent is performing well, but the company wants to improve the agent’s accuracy by providing some specific examples. Which solution meets these requirements?","opts":["Modify the advanced prompts for the agent to include the examples.","Create a guardrail for the agent that includes the examples.","Use Amazon SageMaker Ground Truth to label the examples.","Run a script in AWS Lambda that adds the examples to the training dataset."],"ans":[0],"why":"Providing examples in the agent's advanced prompt is few-shot prompting. It can steer behavior and improve task accuracy without retraining the underlying model.","clue":"improve an agent by providing a few specific examples","tip":"Examples in the prompt → few-shot prompting / advanced prompt customization.","sourceNumber":92},{"q":"Which option is a benefit of using infrastructure as code (IaC) in machine learning operations (MLOps)?","opts":["IaC eliminates the need for hyperparameter tuning.","IaC always provisions powerful compute instances, contributing to the training of more accurate models.","IaC streamlines the deployment of scalable and consistent ML workloads in cloud environments.","IaC minimizes overall expenses by deploying only low-cost instances."],"ans":[2],"why":"IaC makes infrastructure repeatable, versionable, and consistent across environments, which supports reproducible and scalable MLOps deployments.","clue":"benefit of infrastructure as code","tip":"IaC = repeatable, consistent, version-controlled infrastructure—not automatic model tuning or guaranteed cost reduction.","sourceNumber":93},{"q":"A company wants to fine-tune a foundation model (FM) to answer questions for a specific domain. The company wants to use instruction-based fine-tuning. How should the company prepare the training data?","opts":["Gather company internal documents and industry-specific materials. Merge the documents and materials into a single file.","Collect external company reviews from various online sources. Manually label each review as either positive or negative.","Create pairs of questions and answers that specifically address topics related to the company's industry domain.","Create few-shot prompts to instruct the model to answer only domain knowledge."],"ans":[2],"why":"Instruction fine-tuning uses labeled instruction-response examples. Domain-specific question-and-answer pairs directly teach the model how to respond to instructions in the target domain.","clue":"instruction-based fine-tuning","tip":"Instruction fine-tuning → instruction/response or question/answer pairs.","sourceNumber":94},{"q":"Which ML technique can help preserve privacy by allowing models to train across decentralized data sources without centralizing the raw training data?","opts":["Reinforcement learning","Transfer learning","Federated learning","Unsupervised learning"],"ans":[2],"why":"Federated learning trains across decentralized data sources while keeping raw data local, reducing the need to centralize sensitive datasets and supporting privacy-oriented requirements.","clue":"train while keeping sensitive data decentralized","tip":"Data must stay local → federated learning.","sourceNumber":95},{"type":"matching","q":"A company needs to customize a base model that is hosted on Amazon Bedrock. Select the correct model customization method for each company requirement. Each model customization method should be selected one or more times.","rows":["The company wants to improve the model's performance on specific tasks and examples.","The company wants to improve the model's domain knowledge by using additional unlabeled domain documents as training data.","The company wants to retrain the model by using more unlabeled data over time."],"choices":["Continued pre-training","Fine-tuning"],"ans":[1,0,0],"why":"Fine-tuning is driven by task-specific labeled examples and changes model behavior for a specialized task. Continued pre-training uses additional unlabeled domain text to deepen domain knowledge before or instead of task fine-tuning.","clue":"task examples vs additional unlabeled domain data","tip":"Specific labeled task examples → fine-tuning. Unlabeled domain documents → continued pre-training.","sourceNumber":96},{"q":"A manufacturing company has an application that ingests consumer complaints from publicly available sources. The application uses complex hard-coded logic to process the complaints. The company wants to scale this logic across markets and product lines. Which advantage do generative AI models offer for this scenario?","opts":["Predictability of outputs","Adaptability","Less sensitivity to changes in inputs","Explainability"],"ans":[1],"why":"Generative AI models can adapt to varied language, markets, products, and tasks with prompting or customization, reducing dependence on brittle hard-coded rules.","clue":"replace complex hard-coded logic across many markets/product lines","tip":"GenAI advantage across varied tasks and contexts → adaptability.","sourceNumber":97},{"q":"A financial company wants to flag all credit card activity as possibly fraudulent or non-fraudulent based on transaction data. Which type of ML model meets these requirements?","opts":["Regression","Diffusion","Binary classification","Multi-class classification"],"ans":[2],"why":"The target has exactly two discrete labels—fraudulent or non-fraudulent—so this is a binary classification problem.","clue":"two possible categories","tip":"Two labels → binary classification. Numeric value → regression.","sourceNumber":98},{"type":"matching","q":"A company is designing a customer service chatbot by using a fine-tuned large language model (LLM). The company wants to ensure that the chatbot uses responsible AI characteristics. Select the correct responsible AI characteristic for each application design action. Each responsible AI characteristic should be selected one time or not at all.","rows":["Anonymize personal information during training data preparation.","Design the customer service chatbot to provide decision transparency so users can understand how AI is involved in outcomes.","Use Amazon Bedrock Guardrails to prevent harmful output and misuse of the chatbot."],"choices":["Governance","Privacy and security","Safety","Transparency"],"ans":[1,3,2],"why":"Anonymizing personal information protects privacy; making decisions understandable supports transparency when explainability is not offered as a separate choice; and Guardrails that prevent harmful outputs directly support safety.","clue":"PII protection vs understandable decisions vs harmful-output prevention","tip":"PII → privacy/security. Explainable/visible rationale → transparency. Harm prevention → safety.","sourceNumber":99},{"q":"A hospital wants to use a generative AI solution with speech-to-text functionality to help improve employee skills in dictating clinical notes. Which AWS service meets these requirements?","opts":["Amazon Q Developer","Amazon Polly","Amazon Rekognition","AWS HealthScribe"],"ans":[3],"why":"AWS HealthScribe combines speech recognition with generative AI for healthcare conversations and clinical documentation, including transcription and generation of preliminary clinical notes.","clue":"healthcare + speech-to-text + clinical notes + generative AI","tip":"Clinical conversations/notes → AWS HealthScribe. General speech-to-text → Transcribe.","sourceNumber":100},{"q":"A company uses a foundation model (FM) from Amazon Bedrock for an AI search tool. The company wants to fine-tune the model to be more accurate by using the company's data. Which strategy will successfully fine-tune the model?","opts":["Provide labeled data with the prompt field and the completion field.","Prepare the training dataset by creating a .txt file that contains multiple lines in .csv format.","Purchase Provisioned Throughput for Amazon Bedrock.","Train the model on journals and textbooks."],"ans":[0],"why":"Fine-tuning requires labeled input-output training examples. A prompt/completion structure supplies the model with the desired response for each input example.","clue":"fine-tune using company data","tip":"Fine-tuning data → labeled prompt/completion or instruction/response pairs.","sourceNumber":101},{"q":"Which type of AI model makes numeric predictions?","opts":["Diffusion","Regression","Transformer","Multi-modal"],"ans":[1],"why":"Regression predicts a continuous numeric value such as price, demand, or temperature.","clue":"numeric prediction","tip":"Numeric value → regression. Category/label → classification.","sourceNumber":102},{"type":"matching","q":"A company wants to use Amazon SageMaker features for various use cases. Select the correct SageMaker feature for each use case. Each SageMaker feature should be selected one time or not at all.","rows":["Preparing data through a visual interface without using code","Finding and using a prebuilt solution for fraud detection","Create labeled datasets with human intervention"],"choices":["SageMaker Canvas","SageMaker Feature Store","SageMaker Ground Truth","SageMaker JumpStart","SageMaker Model Monitor"],"ans":[0,3,2],"why":"SageMaker Canvas provides a no-code visual ML/data-preparation experience; JumpStart offers prebuilt models and solution templates; and Ground Truth is the human-in-the-loop data labeling service.","clue":"no-code visual prep vs prebuilt solution vs human labeling","tip":"Canvas = no-code. JumpStart = prebuilt. Ground Truth = labeling.","sourceNumber":103},{"q":"What is the purpose of vector embeddings in a large language model (LLM)?","opts":["Splitting text into manageable pieces of data","Grouping a set of characters to be treated as a single unit","Providing the ability to mathematically compare texts","Providing the count of every word in the input"],"ans":[2],"why":"Embeddings map text into numerical vectors. Vector similarity can then be calculated to compare semantic similarity between texts.","clue":"vector embeddings","tip":"Embeddings let you compare meaning mathematically. Chunking splits; tokenization creates tokens.","sourceNumber":104},{"q":"A company wants to fine-tune a foundation model (FM) by using AWS services. The company needs to ensure that its data stays private, safe, and secure in the source AWS Region where the data is stored. Which combination of steps will meet these requirements MOST cost-effectively? (Choose two.)","opts":["Host the model on premises by using AWS Outposts.","Use the Amazon Bedrock API.","Use AWS PrivateLink and a VPC.","Host the Amazon Bedrock API on premises.","Use Amazon CloudWatch logs and metrics."],"ans":[1,2],"why":"Amazon Bedrock is a regional managed service for FM customization and inference, while AWS PrivateLink/VPC endpoints can keep service traffic on the AWS network instead of traversing the public internet. This meets the privacy/network requirement without operating on-premises infrastructure.","clue":"private regional FM access + MOST cost-effective","tip":"Managed Bedrock + private connectivity → Bedrock API + PrivateLink/VPC.","sourceNumber":105},{"q":"A financial company needs to obtain AWS compliance reports and certifications to support an audit of its generative AI environment. Which AWS service provides these documents?","opts":["Amazon Macie","AWS Artifact","AWS Secrets Manager","AWS Config"],"ans":[1],"why":"AWS Artifact is the self-service portal for AWS compliance reports and agreements. It is the exam clue when a company needs documentation demonstrating AWS compliance with regulatory standards.","clue":"compliance reports / evidence of AWS adherence","tip":"Need AWS compliance reports/certifications → AWS Artifact.","sourceNumber":106,"contrast":"AWS Config evaluates resource configuration compliance; Artifact provides AWS audit and compliance documents."},{"q":"A medical company wants to modernize its onsite information processing application. The company wants to use generative AI to respond to medical questions from patients. Which AWS service should the company use to ensure responsible AI for the application?","opts":["Guardrails for Amazon Bedrock","Amazon Inspector","Amazon Rekognition","AWS Trusted Advisor"],"ans":[0],"why":"Amazon Bedrock Guardrails can apply safety controls to generative AI inputs and outputs, including harmful-content filters, denied topics, and sensitive-information handling.","clue":"responsible AI controls for a generative AI application","tip":"Control what a Bedrock model can discuss/output → Guardrails.","sourceNumber":107},{"q":"Which metric is commonly used to compare a generated summary with a reference summary by measuring overlapping text units?","opts":["F1 score","Recall-Oriented Understudy for Gisting Evaluation (ROUGE) score","Accuracy","Mean squared error (MSE)"],"ans":[1],"why":"ROUGE is a reference-overlap family of metrics commonly associated with text summarization. ROUGE-N measures n-gram overlap and ROUGE-L uses longest-common-subsequence style overlap.","clue":"generated summary + reference summary + overlap","tip":"ROUGE → summarization overlap. BLEU → translation overlap. BERTScore → semantic similarity.","sourceNumber":108,"contrast":"The original third-party item omitted ROUGE and offered BLEU instead. This audited version corrects the choices so the question teaches the standard AIF-C01 distinction."},{"q":"What is the benefit of fine-tuning a foundation model (FM)?","opts":["Fine-tuning reduces the FM's size and complexity and enables slower inference.","Fine-tuning uses specific training data to retrain the FM from scratch to adapt to a specific use case.","Fine-tuning keeps the FM's knowledge up to date by pre-training the FM on more recent data.","Fine-tuning improves the performance of the FM on a specific task by further training the FM on new labeled data."],"ans":[3],"why":"Fine-tuning starts from a pre-trained foundation model and further trains it on labeled task-specific examples to specialize its behavior. It does not retrain the model from scratch.","clue":"improve performance on a specific task with labeled data","tip":"Fine-tuning = update weights using labeled examples; RAG = current facts without changing weights.","sourceNumber":109},{"q":"A company wants to improve its chatbot's responses to match the company's desired tone. The company has 100 examples of high-quality conversations between customer service agents and customers. The company wants to use this data to incorporate company tone into the chatbot's responses. Which solution meets these requirements?","opts":["Use Amazon Personalize to generate responses.","Create an Amazon SageMaker HyperPod pre-training job.","Host the model by using Amazon SageMaker. Use TensorRT for large language model (LLM) deployment.","Create an Amazon Bedrock fine-tuning job."],"ans":[3],"why":"The company has labeled examples of the desired conversational style and wants that behavior learned persistently. Bedrock fine-tuning is designed for adapting a foundation model to a target style, format, or task.","clue":"examples of desired tone/style","tip":"Persistent tone/format behavior + examples → fine-tuning.","sourceNumber":110},{"q":"An ecommerce company is using a chatbot to automate the customer order submission process. The chatbot is powered by AI and is available to customers directly from the company's website 24 hours a day, 7 days a week. Which option is an AI system input vulnerability that the company needs to resolve before the chatbot is made available?","opts":["Data leakage","Prompt injection","Large language model (LLM) hallucinations","Concept drift"],"ans":[1],"why":"Prompt injection is an input-side attack in which a user crafts malicious instructions intended to override the application's intended prompt or control flow.","clue":"AI system input vulnerability","tip":"Malicious user input that tries to override instructions → prompt injection.","sourceNumber":111},{"q":"A law firm wants to build an AI application by using large language models (LLMs). The application will read legal documents and extract key points from the documents. Which solution meets these requirements?","opts":["Build an automatic named entity recognition system.","Create a recommendation engine.","Develop a summarization chatbot.","Develop a multi-language translation system."],"ans":[2],"why":"Extracting the main points from long legal documents is a text summarization task, which LLMs are well suited to perform.","clue":"read documents and extract key points","tip":"Condense a document to its main points → summarization.","sourceNumber":112},{"q":"A company wants to use AI to protect its application from threats. The AI solution needs to check if an IP address is from a suspicious source. Which solution meets these requirements?","opts":["Build a speech recognition system.","Create a natural language processing (NLP) named entity recognition system.","Develop an anomaly detection system.","Create a fraud forecasting system."],"ans":[2],"why":"Anomaly detection is designed to identify unusual or suspicious patterns relative to normal behavior and is the best fit among the choices for flagging suspicious network sources.","clue":"identify suspicious/abnormal behavior","tip":"Unusual pattern or outlier → anomaly detection.","sourceNumber":113},{"q":"A social media company wants to prevent users from posting discriminatory or hateful content on the company's application. The company wants to use Amazon Bedrock as part of the solution. How can the company use Amazon Bedrock to meet these requirements?","opts":["Give users the ability to interact based on user preferences.","Use Amazon Bedrock Guardrails content filters to block the Hate category.","Restrict user conversations to predefined topics.","Provide a variety of responses to select from for user engagement."],"ans":[1],"why":"Amazon Bedrock Guardrails content filters include a predefined Hate category for content that discriminates against or dehumanizes people or groups based on identity.","clue":"discriminatory/hateful content","tip":"Hate/violence/insults/sexual/misconduct → Guardrails content filters. Application-specific subjects → denied topics.","sourceNumber":114,"contrast":"The original third-party item used vague 'predefined topics' wording. This audited version uses the correct Guardrails control."},{"q":"An education company wants to build an application. The application will give users the ability to enter text or provide a picture of a question. The application will respond with a written answer and an explanation of the written answer. Which model type meets these requirements?","opts":["Computer vision model","Large multi-modal language model","Diffusion model","Text-to-speech model"],"ans":[1],"why":"A large multimodal language model can accept multiple modalities such as text and images and generate a natural-language answer and explanation.","clue":"input can be text OR image; output is written reasoning","tip":"Multiple input modalities + language output → multimodal LLM.","sourceNumber":115},{"q":"In which stage of the generative AI model lifecycle are tests performed to examine the model's accuracy?","opts":["Deployment","Data selection","Fine-tuning","Evaluation"],"ans":[3],"why":"The evaluation stage measures model quality against selected metrics and test data before or after customization to determine whether the model meets requirements.","clue":"tests performed to examine accuracy","tip":"Measure model performance → evaluation.","sourceNumber":116},{"q":"Which statement correctly describes embeddings in generative AI?","opts":["Embeddings represent data as high-dimensional vectors that capture semantic relationships.","Embeddings is a technique that searches data to find the most helpful information to answer natural language questions.","Embeddings reduce the hardware requirements of a model by using a less precise data type for the weights and activations.","Embeddings provide the ability to store and retrieve data for generative AI applications."],"ans":[0],"why":"Embeddings are high-dimensional numerical vectors that encode semantic information so related items are close in vector space.","clue":"definition of embeddings","tip":"Embeddings = semantic vectors. Retrieval searches them; quantization reduces numeric precision.","sourceNumber":117},{"q":"A company wants to add generative AI functionality to its application by integrating a large language model (LLM). The responses from the LLM must be as deterministic and as stable as possible. Which solution meets these requirements?","opts":["Configure the application to automatically set the temperature parameter to 0 when submitting the prompt to the LLM.","Configure the application to automatically add \"make your response deterministic\" at the end of the prompt before submitting the prompt to the LLM.","Configure the application to automatically add \"make your response deterministic\" at the beginning of the prompt before submitting the prompt to the LLM.","Configure the application to automatically set the temperature parameter to 1 when submitting the prompt to the LLM."],"ans":[0],"why":"Temperature controls randomness in token selection. Setting temperature to 0 (or the lowest supported value) makes outputs as focused and deterministic as the model/API allows.","clue":"deterministic and stable responses","tip":"Low/0 temperature → deterministic. Higher temperature → creativity/randomness.","sourceNumber":118},{"q":"A company needs to select a generative AI model to build an application. The application must provide responses to users in real time. Which model characteristic should the company consider to meet these requirements?","opts":["Model complexity","Innovation speed","Inference speed","Training time"],"ans":[2],"why":"Real-time user interactions depend on how quickly a deployed model can produce outputs, which is inference speed/latency.","clue":"responses in real time","tip":"User-facing response latency → inference speed, not training time.","sourceNumber":119},{"q":"Which term refers to the instructions given to foundation models (FMs) so that the FMs provide a more accurate response to a question?","opts":["Prompt","Direction","Dialog","Translation"],"ans":[0],"why":"A prompt is the input instruction or context supplied to a foundation model to guide its response.","clue":"instructions given to a foundation model","tip":"Instruction/input to an FM → prompt.","sourceNumber":120},{"q":"A retail company wants to build an ML model to recommend products to customers. The company wants to build the model based on responsible practices. Which practice should the company apply when collecting data to decrease model bias?","opts":["Use data from only customers who match the demographics of the company's overall customer base.","Collect data from customers who have a past purchase history.","Ensure that the data is balanced and collected from a diverse group.","Ensure that the data is from a publicly available dataset."],"ans":[2],"why":"Balanced and diverse training data improves representation across relevant groups and reduces the risk that the model systematically favors or underperforms for underrepresented populations.","clue":"decrease model bias during data collection","tip":"Fairness starts with representative, diverse, balanced data.","sourceNumber":121},{"q":"A company is developing an ML model to predict customer churn. Which evaluation metric will assess the model's performance on a binary classification task such as predicting churn?","opts":["F1 score","Mean squared error (MSE)","R-squared","Time used to train the model"],"ans":[0],"why":"F1 is a classification metric that balances precision and recall, making it useful for binary classification such as churn—especially when class balance may be uneven.","clue":"binary classification metric","tip":"Classification → accuracy/precision/recall/F1. Regression → MSE/RMSE/R².","sourceNumber":122},{"q":"An AI practitioner is evaluating the performance of an Amazon SageMaker model. The AI practitioner must choose a performance metric. The metric must show the ratio of the number of correctly classified items to the total number of correctly and incorrectly classified items. Which metric meets these requirements?","opts":["Accuracy","Precision","F1 score","Recall"],"ans":[0],"why":"Accuracy is the number of correct predictions divided by the total number of predictions.","clue":"correct predictions / all predictions","tip":"Accuracy = (TP + TN) / total.","sourceNumber":123},{"q":"Which feature of Amazon OpenSearch Service gives companies the ability to build vector database applications?","opts":["Integration with Amazon S3 for object storage","Support for geospatial indexing and queries","Scalable index management and nearest neighbor search capability","Ability to perform real-time analysis on streaming data"],"ans":[2],"why":"Vector search requires storing vector indexes and performing nearest-neighbor similarity searches. OpenSearch supports scalable indexing and k-NN/nearest-neighbor search for vector database workloads.","clue":"vector database applications","tip":"OpenSearch as a vector DB → vector index + nearest-neighbor search.","sourceNumber":124},{"q":"An ecommerce company receives multiple gigabytes of customer data daily. The company uses the data to train an ML model to forecast future product demand. The company needs a solution to perform inferences once each day. Which inference type meets these requirements?","opts":["Batch inference","Asynchronous inference","Real-time inference","Serverless inference"],"ans":[0],"why":"The company processes a large accumulated dataset on a daily schedule and does not need per-request immediate responses, which is the classic batch inference pattern.","clue":"multiple gigabytes + once each day","tip":"Bulk scheduled inference with no urgency → batch.","sourceNumber":125},{"q":"A company has developed a generative AI model for customer segmentation. The model has been deployed in the company's production environment for a long time. The company recently noticed some inconsistency in the model's responses. The company wants to evaluate model bias and drift. Which AWS service or feature meets these requirements?","opts":["Amazon SageMaker Model Monitor","Amazon SageMaker Clarify","Amazon SageMaker Model Cards","Amazon SageMaker Feature Store"],"ans":[0],"why":"SageMaker Model Monitor is used after deployment to monitor production models for data/model quality drift and can support monitoring of bias drift and feature attribution drift.","clue":"deployed for a long time + bias/drift over time","tip":"Production drift over time → Model Monitor. Bias/explainability analysis itself → Clarify.","sourceNumber":126},{"q":"A company has signed up for Amazon Bedrock access to build applications. The company wants to restrict employee access to specific models available on Amazon Bedrock. Which solution meets these requirements?","opts":["Use AWS Identity and Access Management (IAM) policies to restrict model access.","Use AWS Security Token Service (AWS STS) to generate temporary credentials for model use.","Use AWS Identity and Access Management (IAM) service roles to restrict model subscription.","Use Amazon Inspector to monitor model access."],"ans":[0],"why":"IAM policies can apply least-privilege permissions to Bedrock actions and specific model resources/ARNs, allowing employees to invoke only approved models.","clue":"restrict access to specific Bedrock models","tip":"Permissions/least privilege → IAM policies.","sourceNumber":127},{"q":"Which ML technique uses training data that is labeled with the correct output values?","opts":["Supervised learning","Unsupervised learning","Reinforcement learning","Transfer learning"],"ans":[0],"why":"Supervised learning trains on labeled examples where each input is paired with the known correct target/output.","clue":"labeled with correct output values","tip":"Labeled → supervised. Unlabeled → unsupervised.","sourceNumber":128},{"q":"Which large language model (LLM) parameter controls the number of possible next words or tokens considered at each step of the text generation process?","opts":["Maximum tokens","Top K","Temperature","Batch size"],"ans":[1],"why":"Top K restricts token sampling to the K most probable candidate tokens at each generation step.","clue":"number of candidate next tokens","tip":"Top K = fixed candidate count. Top P = cumulative-probability pool. Temperature = randomness.","sourceNumber":129},{"q":"A company is making a chatbot. The chatbot uses Amazon Lex and Amazon OpenSearch Service. The chatbot uses the company's private data to answer questions. The company needs to convert the data into a vector representation before storing the data in a database. Which type of foundation model (FM) meets these requirements?","opts":["Text completion model","Instruction following model","Text embeddings model","Image generation model"],"ans":[2],"why":"A text embedding model converts text into numerical vectors that can be stored in OpenSearch and searched using semantic similarity.","clue":"convert text/private data into vector representation","tip":"Text → vectors for semantic search/RAG → text embeddings model.","sourceNumber":130}];
